/** เลขไพ่นอกสำรับ = undefined (กฎเหล็กข้อ 14 — ไม่เดาไพ่แทน) */
export function deckMeta(index: number | null | undefined) {
  if (typeof index !== "number" || !Number.isInteger(index)) return undefined;
  const row = DECK_INDEX_META[index];
  return row ? { id: row[0], element: row[1], nameTh: row[2], nameEn: row[3], isMajor: index < 22 } : undefined;
}
